package com.iortatechnxt.brokerverse.eb.domain;

/**
 * Where an EB document came from. Without the partner portal (Drop 2) documents of the client and
 * the insurer arrive by e-mail and are recorded by the EB users with source CLIENT or INSURER.
 */
public enum EbDocumentSource {
  /** Uploaded or generated by the Marketing AO. */
  AO,
  /** Uploaded by Processing. */
  PROCESSING,
  /** Sent by the client. */
  CLIENT,
  /** Sent by an insurer. */
  INSURER,
  /** Generated by BIBS (RA, comparative, TOR). */
  SYSTEM
}
